"use client";

import { loadFont } from "@remotion/google-fonts/Sora";
import { type ReactNode, useId } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type ActivityRingsElementId,
  activityRingsTimeline,
  DEFAULT_RINGS,
  shownRings,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

/** gradients.sh "beam" (#f4f7ff #8fb4ff #3d5bff #1a1660): the hero ring's light. */
const BEAM = {
  stops: ["#C4D6FF", "#8FB4FF", "#3D5BFF", "#3A2FC4"],
  css: "linear-gradient(135deg, #C4D6FF, #8FB4FF 30%, #3D5BFF 66%, #3A2FC4)",
};

export interface ActivityRing {
  label: string;
  /** The number the label counts up to. */
  value: number;
  /** Optional suffix after the value: "h", "k". */
  unit?: string;
  /** How far past the goal the ring laps, as a fraction: 1.14 = 114%. */
  goal?: number;
}

export interface ActivityRingsProps {
  /** Up to three rings, outermost first. */
  rings?: ActivityRing[];
  /** Small heading above the readouts. */
  title?: string;
  accent?: string;
  /** Text after the over-goal percentage. */
  goalLabel?: string;
  /** Frames the outer ring takes to close; inner rings follow 4 frames apart. */
  fill?: number;
  /** Text color of the title and values; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the readouts. Load it yourself; Sora by default. */
  fontFamily?: string;
  /** Size of the rings and readouts, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the fade-in, the push, the title, each readout,
   * each ring's close and the goal hit, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<ActivityRingsElementId>;
}

const EASE_FILL = Easing.bezier(0.55, 0, 0.18, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    key: "radial-gradient(ellipse 38% 62% at 36% 50%, rgba(61,91,255,0.16), rgba(26,22,96,0.10) 55%, transparent 100%)",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.12)",
    neutrals: ["#BEBCB6", "#6A686E"],
    track: 0.13,
    capShadow: "rgba(0,0,0,0.65)",
    grain: 0.07,
  },
  light: {
    bg: "#F5F4F0",
    key: "radial-gradient(ellipse 50% 70% at 36% 46%, rgba(255,255,255,0.95), transparent 70%)",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.12)",
    neutrals: ["#5E5C57", "#B3B0A8"],
    track: 0.11,
    capShadow: "rgba(30,24,16,0.4)",
    grain: 0.045,
  },
} as const;

function rgb(hex: string): number[] | null {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return null;
  const v = Number.parseInt(m[1], 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
}

function alpha(color: string, a: number) {
  const c = rgb(color);
  if (c) return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
  const m = /^rgb\((\d+),(\d+),(\d+)\)$/.exec(color);
  if (m) return `rgba(${m[1]},${m[2]},${m[3]},${a})`;
  return color;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={3}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const fmt = (v: number) => Math.round(v).toLocaleString("en-US");

/** Point on a ring at progress `p` (0 = 12 o'clock, clockwise). */
function at(cx: number, cy: number, r: number, p: number) {
  const a = p * Math.PI * 2;
  return { x: cx + r * Math.sin(a), y: cy - r * Math.cos(a), a };
}

function Ring({
  cx,
  cy,
  r,
  sw,
  p,
  color,
  lapColor,
  track,
  shadow,
  uid,
  u,
}: {
  cx: number;
  cy: number;
  r: number;
  sw: number;
  p: number;
  color: string;
  lapColor: string;
  track: string;
  shadow: string;
  uid: string;
  u: number;
}) {
  const C = 2 * Math.PI * r;
  const clipId = `${uid}c`;
  const blurId = `${uid}b`;
  const base = Math.min(p, 1);
  const lap = Math.max(0, p - 1);
  // the end cap casts a soft shadow forward onto the ring it is about to cover
  const capP = p > 0.75 ? p : 0;
  const end = at(cx, cy, r, capP);
  const fwd = 2.6 * u;
  const capOpacity = interpolate(p, [0.8, 1], [0, 1], CLAMP);
  const rot = `rotate(-90 ${cx} ${cy})`;
  return (
    <g>
      <defs>
        <clipPath id={clipId}>
          <path
            clipRule="evenodd"
            d={`M ${cx - r - sw / 2} ${cy} a ${r + sw / 2} ${r + sw / 2} 0 1 0 ${2 * r + sw} 0 a ${r + sw / 2} ${r + sw / 2} 0 1 0 ${-(2 * r + sw)} 0 Z M ${cx - r + sw / 2} ${cy} a ${r - sw / 2} ${r - sw / 2} 0 1 0 ${2 * r - sw} 0 a ${r - sw / 2} ${r - sw / 2} 0 1 0 ${-(2 * r - sw)} 0 Z`}
          />
        </clipPath>
        <filter id={blurId} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation={2.6 * u} />
        </filter>
      </defs>
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="none"
        stroke={track}
        strokeWidth={sw}
      />
      {base > 0.001 ? (
        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke={color}
          strokeWidth={sw}
          strokeLinecap={base >= 1 ? "butt" : "round"}
          strokeDasharray={base >= 1 ? undefined : `${base * C} ${C}`}
          transform={rot}
        />
      ) : null}
      {capP > 0 ? (
        <g clipPath={`url(#${clipId})`} opacity={capOpacity}>
          <circle
            cx={end.x + Math.cos(end.a) * fwd}
            cy={end.y + Math.sin(end.a) * fwd}
            r={sw / 2}
            fill={shadow}
            filter={`url(#${blurId})`}
          />
        </g>
      ) : null}
      {lap > 0.0005 ? (
        <circle
          cx={cx}
          cy={cy}
          r={r}
          fill="none"
          stroke={lapColor}
          strokeWidth={sw}
          strokeLinecap="round"
          strokeDasharray={`${lap * C} ${C}`}
          transform={rot}
        />
      ) : capP > 0 ? (
        // redraw the cap over its own shadow while still inside the first lap
        <circle cx={end.x} cy={end.y} r={sw / 2} fill={color} />
      ) : null}
    </g>
  );
}

export function ActivityRings(props: ActivityRingsProps) {
  const {
    rings = DEFAULT_RINGS,
    title = "This month",
    accent = "#3B5BFD",
    goalLabel = "of goal",
    ink,
    background,
    fontFamily = sans,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    activityRingsTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const t = frame * speed;
  const u = Math.min(width / 1280, height / 720);
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const list = shownRings(rings);

  // hero ring carries the gradient; the others stay neutral so the data reads
  const gradId = `${uid}beam`;
  const colors = [accent, c.neutrals[0], c.neutrals[1]];
  const paints = [`url(#${gradId})`, c.neutrals[0], c.neutrals[1]];
  const swatches = [BEAM.css, c.neutrals[0], c.neutrals[1]];

  const cx = width * 0.355;
  const cy = height * 0.5;
  const sw = 26 * u;
  const gap = 8 * u;
  const R0 = 182 * u;
  const radius = (i: number) => R0 - i * (sw + gap);

  const goalEl = tl.get("goal");
  const HIT = goalEl.start;
  const stageEl = tl.get("stage");
  const pushEl = tl.get("push");
  const titleEl = tl.get("title");

  const stageIn = interpolate(t, [stageEl.start, stageEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const progress = (i: number) => {
    const goal = Math.max(1, list[i].goal ?? 1);
    const ringEl = tl.get(`ring:${i}`);
    const p1 = interpolate(t, [ringEl.start, ringEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_FILL,
    });
    if (t < HIT) return p1;
    const s = spring({
      frame: t - HIT - i * goalEl.beat("lap"),
      fps,
      config: { damping: 15, mass: 0.9, stiffness: 120 },
    });
    return 1 + (goal - 1) * s;
  };

  // the hit: a small bump of the whole object and a check in the centre
  const bump = interpolate(
    t,
    [HIT, HIT + goalEl.beat("bumpPeak"), HIT + goalEl.beat("bumpEnd")],
    [0, 1, 0],
    { ...CLAMP, easing: Easing.bezier(0.65, 0, 0.35, 1) },
  );
  const check = spring({
    frame: t - HIT - goalEl.beat("check"),
    fps,
    config: { damping: 13, mass: 0.6, stiffness: 160 },
  });
  const checkDraw = interpolate(
    t,
    [HIT + goalEl.beat("checkAt"), HIT + goalEl.beat("checkEnd")],
    [0, 1],
    { ...CLAMP, easing: EASE_OUT },
  );
  const pulse = interpolate(t, [HIT, goalEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const push = interpolate(t, [pushEl.start, pushEl.end], [0, 1], CLAMP);
  const innerR = radius(list.length - 1) - sw / 2;
  const badge = Math.min(32 * u, innerR * 0.42);

  // readouts
  const rowX = width * 0.6;
  const rowH = 108 * u;
  const rowsTop = cy - (list.length * rowH) / 2 + 18 * u;
  const titleSpan = [titleEl.start, titleEl.end];
  const ruleSpan = [
    titleEl.start + titleEl.beat("rule"),
    titleEl.end + titleEl.beat("rule"),
  ];
  const readoutSpan = (i: number) => {
    const e = tl.get(`readout:${i}`);
    return [e.start, e.end];
  };
  const rowAt = (tt: number, span: number[]) =>
    interpolate(tt, span, [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const row = (span: number[]) => rowAt(t, span);
  // Whether a travel of `px` at full stroke is still moving at this frame.
  const stirs = (at: (tt: number) => number, px: number) =>
    Math.abs(at(t + 1) - at(t)) * px > 1e-3 ||
    Math.abs(at(t) - at(t - 1)) * px > 1e-3;
  const overInAt = (tt: number, i: number) =>
    interpolate(
      tt,
      [
        HIT + goalEl.beat("overAt") + i * goalEl.beat("overStep"),
        HIT + goalEl.beat("overEnd") + i * goalEl.beat("overStep"),
      ],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );

  return (
    <AbsoluteFill
      style={{
        background: background ?? c.bg,
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          background: c.key,
        }}
      />

      <ScaleLayer scale={scale}>
        {/* rings plane: moves a touch more than the readouts for parallax */}
        <AbsoluteFill
          style={{
            transform: `translateX(${-push * 10 * u}px) scale(${(0.94 + stageIn * 0.06) * (1 + push * 0.02) * (1 + bump * 0.016)})`,
            transformOrigin: `${cx}px ${cy}px`,
            opacity: stageIn,
          }}
        >
          <svg
            width={width}
            height={height}
            viewBox={`0 0 ${width} ${height}`}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <defs>
              {/* fixed in space, drifting a few degrees: light falls from the top right */}
              <linearGradient
                id={gradId}
                gradientUnits="userSpaceOnUse"
                x1={cx + R0 * Math.cos(-0.9 + push * 0.25)}
                y1={cy + R0 * Math.sin(-0.9 + push * 0.25)}
                x2={cx - R0 * Math.cos(-0.9 + push * 0.25)}
                y2={cy - R0 * Math.sin(-0.9 + push * 0.25)}
              >
                {BEAM.stops.map((col, k) => (
                  <stop
                    key={col}
                    offset={k / (BEAM.stops.length - 1)}
                    stopColor={col}
                  />
                ))}
              </linearGradient>
            </defs>
            {list.map((ring, i) => (
              <Ring
                key={ring.label}
                cx={cx}
                cy={cy}
                r={radius(i)}
                sw={sw}
                p={progress(i)}
                color={paints[i]}
                lapColor={paints[i]}
                track={alpha(i === 0 ? BEAM.stops[2] : colors[i], c.track)}
                shadow={c.capShadow}
                uid={`${uid}r${i}`}
                u={u}
              />
            ))}
            {/* hit pulse just outside the outer ring */}
            {t >= HIT ? (
              <circle
                cx={cx}
                cy={cy}
                r={R0 + sw / 2 + 6 * u + pulse * 26 * u}
                fill="none"
                stroke={accent}
                strokeWidth={Math.max(1, 1.5 * u)}
                opacity={(1 - pulse) * 0.45}
              />
            ) : null}
            {/* centre check */}
            {t >= HIT ? (
              <g
                transform={`translate(${cx} ${cy}) scale(${0.82 + check * 0.18})`}
                opacity={Math.min(1, check * 1.6)}
              >
                <circle r={badge} fill={`url(#${gradId})`} />
                <path
                  d={`M ${-badge * 0.36} ${badge * 0.02} L ${-badge * 0.1} ${badge * 0.28} L ${badge * 0.38} ${-badge * 0.24}`}
                  fill="none"
                  stroke="#FFFFFF"
                  strokeWidth={badge * 0.15}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray="1 1"
                  strokeDashoffset={1 - checkDraw}
                />
              </g>
            ) : null}
          </svg>
        </AbsoluteFill>

        {/* readouts */}
        <AbsoluteFill
          style={{
            transform: `translateX(${-push * 5 * u}px)`,
            fontFamily,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: rowX,
              top: rowsTop - 58 * u,
              display: "flex",
              alignItems: "center",
              gap: 12 * u,
              opacity: row(titleSpan),
              transform: `translateY(${(1 - row(titleSpan)) * 10 * u}px)${glide(stirs((tt) => rowAt(tt, titleSpan), 10 * u))}`,
            }}
          >
            <span
              style={{
                color: fg,
                fontWeight: 500,
                fontSize: 18 * u,
                letterSpacing: "-0.01em",
              }}
            >
              {title}
            </span>
            <span
              style={{
                width: 200 * u * row(ruleSpan),
                height: Math.max(1, u),
                background: c.hair,
              }}
            />
          </div>
          {list.map((ring, i) => {
            const p = progress(i);
            const v = ring.value * Math.min(1, p);
            const over = Math.round((p - 1) * 100);
            const overIn = overInAt(t, i);
            const r = row(readoutSpan(i));
            const rising = stirs((tt) => rowAt(tt, readoutSpan(i)), 80 * u);
            return (
              <div
                key={ring.label}
                style={{
                  position: "absolute",
                  left: rowX,
                  top: rowsTop + i * rowH,
                  display: "flex",
                  flexDirection: "column",
                  gap: 6 * u,
                  overflow: "hidden",
                  paddingBottom: 4 * u,
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 10 * u,
                    transform: `translateY(${(1 - r) * 120}%)${glide(rising)}`,
                  }}
                >
                  <span
                    style={{
                      width: 10 * u,
                      height: 10 * u,
                      borderRadius: "50%",
                      background: swatches[i],
                    }}
                  />
                  <span
                    style={{
                      color: c.muted,
                      fontWeight: 400,
                      fontSize: 17 * u,
                      letterSpacing: "-0.005em",
                    }}
                  >
                    {ring.label}
                  </span>
                </div>
                <div
                  style={{
                    display: "flex",
                    alignItems: "baseline",
                    gap: 12 * u,
                    transform: `translateY(${(1 - r) * 110}%)${glide(rising)}`,
                  }}
                >
                  <span
                    style={{
                      fontWeight: 400,
                      fontSize: 64 * u,
                      lineHeight: 1,
                      letterSpacing: "-0.045em",
                      fontVariantNumeric: "tabular-nums",
                      color: fg,
                    }}
                  >
                    {fmt(v)}
                    {ring.unit ? (
                      <span style={{ color: c.muted, fontSize: 30 * u }}>
                        {ring.unit}
                      </span>
                    ) : null}
                  </span>
                  {over > 0 ? (
                    <span
                      style={{
                        fontWeight: 400,
                        fontSize: 16 * u,
                        color: c.muted,
                        fontVariantNumeric: "tabular-nums",
                        opacity: overIn,
                        transform: `translateY(${(1 - overIn) * 8 * u}px)${glide(stirs((tt) => overInAt(tt, i), 8 * u))}`,
                      }}
                    >
                      +{over}% {goalLabel}
                    </span>
                  ) : null}
                </div>
              </div>
            );
          })}
        </AbsoluteFill>
      </ScaleLayer>

      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The rings fading in, the slow push, the title and each readout rising in,
// each ring closing (outermost first), and the goal hit: the rings lapping
// past their goal, the check and the pulse, the over-goal percentages.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids
// are public: a saved `timing` prop refers to them.

export type ActivityRingsElementId =
  | "stage"
  | "push"
  | "title"
  | `readout:${number}`
  | `ring:${number}`
  | "goal";

interface Ring {
  label: string;
  value: number;
  unit?: string;
  goal?: number;
}

export interface ActivityRingsTimingProps {
  rings?: Ring[];
  fill?: number;
}

export const DEFAULT_RINGS: Ring[] = [
  { label: "Renders", value: 1284, goal: 1.14 },
  { label: "Templates", value: 42, goal: 1.08 },
  { label: "Hours saved", value: 310, goal: 1.05 },
];

/** The rings drawn: the first three, outermost first. */
export function shownRings<R extends Ring>(rings: R[]) {
  return rings.slice(0, 3);
}

const FILL_START = 16;
const RING_GAP = 4;

// `title` raises the heading over its length and draws its rule from
// `rule`. `readout:<i>` raises ring `i`'s label and value; a chain.
// `ring:<i>` closes ring `i` over its length, `RING_GAP` after the one
// outside it; a chain. `goal` starts when the last ring closes: ring `i`
// laps past its goal `lap` × i frames in, the check springs in from
// `check` and draws from `checkAt` to `checkEnd`, the object bumps to
// `bumpPeak` and back by `bumpEnd`, the pulse runs over the length, and
// the over-goal figures rise from `overAt` to `overEnd`, `overStep` apart.
export const activityRingsTimeline = defineTimeline<
  ActivityRingsElementId,
  ActivityRingsTimingProps
>(({ rings = DEFAULT_RINGS, fill = 42 }) => {
  const list = shownRings(rings);
  const fillEnd = (i: number) => FILL_START + fill + i * RING_GAP;
  const HIT = fillEnd(list.length - 1);
  const elements: TimelineElement<ActivityRingsElementId>[] = [
    { id: "stage", lane: "Rings", label: "Fade in", start: 0, length: 22 },
    { id: "push", lane: "Camera", label: "Push", start: 0, length: HIT + 60 },
    {
      id: "title",
      lane: "Readouts",
      label: "Title",
      start: 2,
      length: 18,
      beats: { rule: 4 },
    },
    ...list.map(
      (ring, i): TimelineElement<ActivityRingsElementId> => ({
        id: `readout:${i}`,
        lane: "Readouts",
        label: ring.label,
        start: 8 + (i + 1) * 4,
        length: 18,
        follows: i > 0 ? `readout:${i - 1}` : "title",
      }),
    ),
    ...list.map(
      (ring, i): TimelineElement<ActivityRingsElementId> => ({
        id: `ring:${i}`,
        lane: "Rings",
        label: ring.label,
        start: FILL_START + i * RING_GAP,
        length: fill,
        follows: i > 0 ? `ring:${i - 1}` : undefined,
      }),
    ),
    {
      id: "goal",
      lane: "Rings",
      label: "Goal",
      start: HIT,
      length: 20,
      follows: list.length > 0 ? `ring:${list.length - 1}` : undefined,
      beats: {
        lap: 2,
        check: 1,
        checkAt: 3,
        checkEnd: 13,
        bumpPeak: 5,
        bumpEnd: 16,
        overAt: 4,
        overEnd: 16,
        overStep: 3,
      },
    },
  ];
  return elements.sort((a, b) => a.start - b.start);
});
